from pathlib import Path
p=Path('.')
def write(f,s): (p/f).write_text(s,encoding='utf-8')
def edit(f,a,b):
 q=p/f;s=q.read_text(encoding='utf-8-sig');assert a in s,(f,a);q.write_text(s.replace(a,b),encoding='utf-8')
write('inventory-render.js', '''import {itemTypes} from './inventory.js?v=shield28';
import {snapPixel,animationTime} from './pixel-grid.js?v=shield28';
const image=new Image(),cells=[];image.src='assets/pixel/inventory-sprites.png';image.onload=()=>{const c=document.createElement('canvas');c.width=image.width;c.height=image.height;const g=c.getContext('2d');g.drawImage(image,0,0);const data=g.getImageData(0,0,c.width,c.height).data;for(let n=0;n<16;n++){const x0=n%4*c.width/4,y0=Math.floor(n/4)*c.height/4;let l=x0+c.width/4,r=x0,t=y0+c.height/4,b=y0;for(let y=y0;y<y0+c.height/4;y++)for(let x=x0;x<x0+c.width/4;x++)if(data[(y*c.width+x)*4+3]>30){l=Math.min(l,x);r=Math.max(r,x);t=Math.min(t,y);b=Math.max(b,y);}cells[n]={x:l,y:t,w:r-l+1,h:b-t+1};}};
export function drawItemSprite(ctx,n,x,y,w=32,h=32){const c=cells[n];if(c)ctx.drawImage(image,c.x,c.y,c.w,c.h,snapPixel(x-w/2),snapPixel(y-h),snapPixel(w),snapPixel(h));}
export function drawInventoryWorld(ctx,s,text,box){const g=s.machine,c=s.level.accent,t=animationTime(s.time);
 for(const i of s.items){drawItemSprite(ctx,i.locked?14:itemTypes[i.type].icon,i.x,i.y+44,i.locked?44:30,i.locked?44:30);text(i.locked?'SWORD · CONTAINER':'USE · '+itemTypes[i.type].name.toUpperCase(),i.x,i.y-10,c,10);}
 for(const b of s.bombs){drawItemSprite(ctx,10,b.x,b.y+12,26,26);text(b.fuse.toFixed(1)+'s',b.x,b.y-24,'#ffbc78',12);}
 if(s.blast&&s.time-s.blast.time<.5){const age=s.time-s.blast.time;ctx.strokeStyle=age<.12?'#fff8b2':'#ff8d55';ctx.lineWidth=6;ctx.beginPath();ctx.arc(snapPixel(s.blast.x),snapPixel(s.blast.y),snapPixel(10+age*190),0,Math.PI*2);ctx.stroke();text('BOOM',s.blast.x,s.blast.y-30,'#ffe8b0',20);}
 if(s.round===6){drawItemSprite(ctx,12,620,610,86,52);text('MIX · '+g.ingredients.length+'/2',620,535,c,12);drawItemSprite(ctx,13,1000,610,112,126);text('OVEN · '+['OFF','WARM','HOT'][g.ovenMode],1000,470,c,12);if(g.oven||g.baked)text(g.baked?'DING! USE TO COLLECT':Math.round(g.cook/3*100)+'% · EXHAUST →',1000,450,'#fff5bc',12);box('#1c262c',1200,540,38,70);drawItemSprite(ctx,3,1218,576,22,22);text(s.power?'TICKET ACCEPTED':'USE TICKET',1218,520,c,11);}
 if(s.round===7){drawItemSprite(ctx,9,630,610,90,90);if(g.lens)drawItemSprite(ctx,itemTypes[g.lens].icon,650,565,28,28);text((g.lamp?'UV ON':'INSTALL LAMP')+' · '+(g.angle?'HIGH':'LOW'),630,500,c,11);text('SUNSET ABOVE · OCEAN BELOW',880,190,c,13);
  for(const [x,y,color,on,name] of [[780,330,'#ff837e',g.sunset,'SUNSET'],[1170,580,'#8ea9ff',g.ocean,'OCEAN']]){drawItemSprite(ctx,color==='#ff837e'?7:8,x,y+25,40,40);text(name+(on?' ✓':''),x,y-30,color,11);}
  if(g.lamp&&g.lens){ctx.strokeStyle=g.lens==='red'?'#ff847f':'#7da3ff';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(650,555);ctx.lineTo(g.lens==='red'?780:1170,g.angle?330:580);ctx.stroke();}
  if(!g.motor){ctx.strokeStyle='#726b88';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(870,320);ctx.lineTo(snapPixel(g.bladeX||870),snapPixel(g.bladeY||525));ctx.stroke();drawItemSprite(ctx,7,g.bladeX||870,(g.bladeY||525)+22,44,44);}drawItemSprite(ctx,14,930,610,34,50);text(g.motor?'MOTOR CUT':'SWORD · MOTOR',930,530,c,11);
 }
 if(s.round===8){drawItemSprite(ctx,10,520,610,54,60);text('USE · BOMB DISPENSER',520,528,c,11);if(!g.gate){drawItemSprite(ctx,14,834,610,48,100);text('BLAST GATE',834,490,c,11);}if(!g.safe)drawItemSprite(ctx,15,970,390,94,82);text(g.safe?'SAFE OPEN':'BLAST SAFE',970,290,c,11);drawItemSprite(ctx,11,1260,610,40,64);text(s.power?'UNLOCKED':'USE NEON KEY',1260,526,c,11);}
 if(s.round>=6){for(const wall of s.round===6?[{x:1240,on:!s.power}]:s.round===7?[{x:700,on:!g.sunset},{x:1100,on:!g.ocean}]:[]){if(wall.on){for(let y=200;y<610;y+=32)box(c+'99',wall.x,y,24,24);}}text(s.power?'EXIT · ALL THREE':'EXIT LOCKED',s.level.exit.x,472,c,12);ctx.strokeStyle=s.power?'#bfff8c':'#897787';ctx.lineWidth=6;ctx.strokeRect(1305,500,70,110);}
}
''')
